 function groupTitle(g){return `${g.meta.department} · ${say('المرحلة','Stage')} ${g.meta.stage} · ${g.meta.period==='morning'?say('صباحي','Morning'):g.meta.period==='evening'?say('مسائي','Evening'):say('الدراسة غير مذكورة','Study period not specified')} · ‎${g.meta.year||say('السنة غير مذكورة','Year not specified')}‎`;}
