 function setupColumnFilters(){filterDialog=document.createElement('dialog');filterDialog.id='consolidationColumnFilter';filterDialog.setAttribute('aria-labelledby','consolidationColumnTitle');filterDialog.innerHTML='<strong id="consolidationColumnTitle" tabindex="-1"></strong><input id="consolidationColumnSearch" type="search" aria-label="بحث في قيم العمود"><label class="consolidationColumnAll"><input id="consolidationColumnAll" type="checkbox"><span id="consolidationColumnAllText"></span></label><div id="consolidationColumnValues"></div><div class="consolidationColumnActions"><button id="consolidationColumnApply" type="button"></button><button id="consolidationColumnCancel" type="button"></button></div>';document.body.append(filterDialog);$('consolidationColumnSearch').oninput=()=>{paintColumnFilter();positionColumnFilter();};$('consolidationColumnAll').onchange=e=>{for(const v of filterOptions())e.target.checked?filterDraft.add(v):filterDraft.delete(v);paintColumnFilter();};$('consolidationColumnCancel').onclick=()=>filterDialog.close();$('consolidationColumnApply').onclick=()=>{const g=rawGroups().find(g=>g.id===currentColumn.group),all=(g?.students||[]).map(s=>columnValue(s,currentColumn));if(all.every(v=>filterDraft.has(v)))columnFilters.delete(columnKey(currentColumn));else columnFilters.set(columnKey(currentColumn),{column:currentColumn,values:new Set(filterDraft)});filterDialog.close();pages.clear();results();[...document.querySelectorAll('[data-consolidation-column]')].find(th=>th.dataset.consolidationColumn===columnKey(currentColumn))?.focus({preventScroll:true});};filterDialog.addEventListener('close',()=>{if(filterAnchor?.isConnected)filterAnchor.focus({preventScroll:true});});window.addEventListener('resize',positionColumnFilter);}
